@section('content')<section class="tr-page"><div class="tr-shell"><div class="tr-page-head"><div><span class="tr-eyebrow">Account</span><h1>My wishlist</h1><p>Save products now and decide later.</p></div>@if($wishlist->isNotEmpty())<form method="POST" action="{{ route('user.wishlist.clear') }}" onsubmit="return confirm('Clear your wishlist?')">@csrf @method('DELETE')<button type="submit" class="btn btn-outline-danger">Clear all</button></form>@endif</div><div class="tr-account-grid">@include('frontend.partials.account-nav')<div class="tr-stack">@forelse($wishlist as $item)<article class="tr-card tr-wishlist-row" id="wishlist-item-{{ $item->id }}"><a href="{{ route('products.show',$item->product->slug) }}"><img src="{{ $item->product->thumbnail_url }}" alt="{{ $item->product->name }}"></a><div><span class="tr-eyebrow">{{ $item->product->category?->name ?? 'Product' }}</span><h5 class="mb-1">{{ $item->product->name }}</h5><div><strong>{{ App\Models\Setting::get('currency_symbol','Rs') }} {{ number_format($item->product->price,2) }}</strong>@if($item->product->compare_price>$item->product->price)<del class="text-muted ms-2">{{ App\Models\Setting::get('currency_symbol','Rs') }} {{ number_format($item->product->compare_price,2) }}</del>@endif</div><small class="{{ $item->product->stock_quantity>0?'text-success':'text-danger' }}">{{ $item->product->stock_quantity>0?'In stock':'Out of stock' }}</small></div><div class="tr-wishlist-actions">@if($item->product->stock_quantity>0)<button class="btn btn-sm btn-primary" onclick="addWishToCart({{ $item->product->id }},this)"><i class="fa-solid fa-bag-shopping me-1"></i>Add to cart</button>@endif<form method="POST" action="{{ route('compare.add',$item->product) }}">@csrf<button class="btn btn-sm btn-outline-light"><i class="fa-solid fa-scale-balanced"></i></button></form><button class="btn btn-sm btn-outline-danger" onclick="removeWish({{ $item->id }})"><i class="fa-regular fa-trash-can"></i></button></div></article>@empty<div class="tr-empty tr-card"><i class="fa-regular fa-heart"></i><h4>Your wishlist is empty</h4><p>Save products from the shop and they will appear here.</p><a class="btn btn-primary" href="{{ route('products.index') }}">Explore products</a></div>@endforelse</div></div></div></section>
@push('scripts')<script>
function removeWish(id){if(!confirm('Remove this item?'))return;fetch('{{ url('/wishlist/remove') }}/'+id,{method:'DELETE',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'}}).then(r=>r.json()).then(d=>{if(d.success){document.getElementById('wishlist-item-'+id)?.remove();Trendora.toast(d.message,'success')}})}
function addWishToCart(productId,btn){btn.disabled=true;fetch('{{ route('cart.add') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({product_id:productId,quantity:1})}).then(r=>r.json()).then(d=>{Trendora.toast(d.message,d.success?'success':'error')}).finally(()=>btn.disabled=false)}
</script>@endpush
@endsection
